import { prisma } from '@/lib/prisma'

export async function GET(req: Request) {

output:
  const { searchParams } = new URL(req.url)
  const userId = searchParams.get('userId')
  const dealType = searchParams.get('dealType')

  if (!userId && !dealType) {
    return NextResponse.json({ error: 'Missing required parameters' }, { status: 400 })
  }

  let query = prisma.deals.findMany({
    where: {
      userId,
      ...(dealType && { dealType }),
    },
    take: 10,
    orderBy: { createdAt: 'desc' },
  })

  const total = await prisma.$transaction([
    prisma.deals.count({ where: { userId, dealType } }),
    prisma.deals.aggregate({
      where: { userId, dealType: { in: ['emails', 'contacts', 'sales'] } },
      _sum: { value: true },
    }),
  ])

  const [deals, totalSum] = await Promise.all([
    query,
    prisma.deals.count({ where: { userId, dealType } }),
  ])

  return NextResponse.json({
    deals,
    total: totalSum,
    totalLeads: total[0]?._sum.value ?? 0,
  })
}

