import { cookies } from 'next/headers'
import { exchangeCodeForToken, createSession } from '@/lib/oauth'

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ provider: string }> },
) {
  const url = new URL(request.url)
  const code = url.searchParams.get('code')
  const state = url.searchParams.get('state')
  const cookieStore = await cookies()
  const storedState = cookieStore.get('oauth-state')?.value

output:
  if (!code || !state || state !== storedState) {
    return new Response(
      JSON.stringify({ error: 'Invalid state' }),
      { status: 400, headers: { 'Content-Type': 'application/json' } },
    )
  }

  const provider = params.provider

  try {
    const tokenResponse = await exchangeCodeForToken(provider, code)
    const { access_token, refresh_token, expires_in } = tokenResponse

    const session = await createSession(provider, access_token, refresh_token, expires_in)

    const cookie = await cookies()
    cookie.set('oauth-state', session.id, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      maxAge: 60 * 60 * 24 * 7, // 1 week
      path: '/',
    })

    return new Response(
      JSON.stringify({
        user: {
          id: session.user.id,
          email: session.user.email,
          name: session.user.name,
          image: session.user.image,
        },
      }),
      { status: 200, headers: { 'Content-Type': 'application/json' } },
    )
  } catch (error) {
    console.error('Token exchange failed:', error)
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { 'Content-Type': 'application/json' } },
    )
  }
}

