const passwordResetRequest: NextApiRequest = async (req) => {
  const session = await getSession(req, res)

  const body = await req.json()
  const parsed = passwordResetSchema.safeParse(body)

  if (!parsed.success) {
    return res.status(400).json

  const ref = useRef<T | null>(null)

  useEffect(() => {
    const listener = (event: Event) => {
      // Check if the event target is outside the ref's current DOM tree
      // This is a simplified check; in reality you might need to consider
      // using `contains` instead of `containsElement`
      const target = event.target as HTMLElement
      if (ref.current && target.contains(ref.current)) {
        handler()
      }
    }

    document.addEventListener('mousedown', listener)
    document.addEventListener('touchstart', listener)

    return () => {
      document.removeEventListener('mousedown', listener)
      document.removeEventListener('touchstart', listener)
    }
  }, [handler])

  return ref
}

