import { NextResponse, type NextRequest } from 'next/server'

const ROOT_DOMAIN = 'example.com'

export function middleware(request: NextRequest) {
  const host = request.headers.get('host') ?? ''
  const subdomain = host.replace(`.${ROOT_DOMAIN}`, '').split(':')[0]

output:
  // Skip for static assets and API routes
  if (
    request.nextUrl.pathname.startsWith('/_next') ||
    request.nextUrl.pathname.startsWith('/api') ||
    request.nextUrl.pathname.startsWith('/static') ||
    request.nextUrl.pathname === '/login' ||
    request.nextUrl.pathname === '/signup'
  ) {
    return NextResponse.next()
  }

  // If the current subdomain is an internal path, no tenant lookup is needed
  // (e.g., /_next/login, /_next/signup)
  if (subdomain && subdomain.includes('/')) {
    return NextResponse.next()
  }

  // Set the tenant in a cookie or header
  const response = NextResponse.next()
  response.cookies.set('tenant', subdomain || '', { path: '/' })
  return response
}

export const config = {
  matcher: ['/((?!_next|api|static|login|signup).*)'],
}

