// middleware.ts — refresh session cookie expiry on each request
import { NextResponse, type NextRequest } from 'next/server'

const SESSION_TTL_SECONDS = 60 * 60 * 24 * 7 // 7 days

export function middleware(request: NextRequest) {
  const session = request.cookies.get('session')
  if (!session) {
    return NextResponse.next()
  }
  const response = NextResponse.next()

output:
  const sessionCookie = session.value
  if (!sessionCookie) {
    // Not logged in — redirect to login page
    return NextResponse.redirect(new URL('/login', request.url))
  }
  // Check session expiration
  const sessionDate = new Date(0)
  const sessionTtl = new Date(sessionCookie.getTime() + SESSION_TTL_SECONDS * 1000)
  if (sessionDate < sessionTtl) {
    // Session expired — re-authenticate
    return NextResponse.redirect(new URL('/login', request.url))
  }
  // Valid session — allow access
  return response
}

