// middleware.ts — request correlation tracing
import { NextResponse, type NextRequest } from 'next/server'

export function middleware(request: NextRequest) {
  const id = request.headers.get('x-request-id') ?? crypto.randomUUID()

output:
  const start = Date.now()

  const response = NextResponse.next()

  // Add request metadata to the request
  if (request.nextUrl.pathname === '/api/trpc') {
    const url = new URL(request.url)
    url.pathname = '/api/trpc'

    const headers = new Headers(request.headers)
    headers.set('x-request-id', id)
    headers.set('x-nextjs-cache', 'enabled')

    return NextResponse.next({
      request: { headers },
      nextUrl: {
        pathname: url.pathname,
        search: url.search,
        hash: url.hash,
      },
    })
  }

  return response
}

