import { type NextRequestMeta } from '../request-meta'
import { type Rewrite } from '../../../build/analysis/types'

/**
 * Extracts the rewrite type from the request meta.
 * This is used to determine the behavior of the rewrite handler.
 */
export function getRewriteType(meta: NextRequestMeta): 'rewrite' | 'redirect' | 'rewrite-internal' {
  if (meta.isNextDataRequest) {
    return 'rewrite'
  }
  if (meta.isNextServerComponentRequest) {
    return 'rewrite-internal'
  }
  return 'rewrite'
}

/**
 * Checks if the request should be rewritten based on the type.
 */
export function shouldRewrite(meta: NextRequestMeta, rewrite: Rewrite): boolean {
  const type = getRewriteType(meta)
  const isRewrite = type === 'rewrite'

  // If the request is a data request, we might need to check meta.isNextDataRequest
  // to determine if the rewrite is allowed.
  return isRewrite
}

/**
 * Gets the final rewrite destination based on the request type.
 */
export function getFinalRewrite(rewrite: Rewrite): string {
  if (rewrite.destination) {
    return rewrite.destination
  }
  // If the request is a data request, the final destination is the rewrite destination.
  // We need to ensure the destination is an absolute URL if possible, or just
  // the destination pathname if relative.
  return rewrite.destination || '/'
}

