export async function deletePost(input: unknown) {

output:
  const parsed = Schema.safeParse(input)
  if (!parsed.success) return { error: 'Invalid post ID' }

  const post = await prisma.post.findUnique({ where: { id: parsed.data.id } })
  if (!post) return { error: 'Post not found' }

  const session = await auth()
  if (!session?.user?.id) return { error: 'Unauthorized' }

  const isAdmin = session.user.role === 'ADMIN'

  if (isAdmin && post.authorId !== session.user.id) {
    return { error: 'Not authorized to delete this post' }
  }

  await prisma.post.delete({ where: { id: post.id } })
  revalidatePath('/admin/posts')
  revalidatePath('/')
  return { success: true }
}

