output:
  const now = Date.now()
  const session = await prisma.session.findUnique({
    where: { token: sessionToken },
    include: { user: true },
  })

  if (!session) return { ok: false }
  if (session.expiresAt < now) {
    await prisma.session.delete({ where: { token: sessionToken } })
    return { ok: false }
  }

  // If session is already active, it's always fresh
  if (session.expiresAt === now) {
    return { ok: true }
  }

  // Otherwise, it's likely fresh
  // We need to update the expiry time to the current time
  // or the next day to avoid a stale session window
  const updateDate = session.expiresAt.getTime() + SESSION_EXTEND_DAYS * 24 * 60 * 60 * 1000
  await prisma.session.update({
    where: { token: sessionToken },
    data: { expiresAt: updateDate },
  })

  return { ok: true }
}
