 */
export async function getUserById(id: string): Promise<User | null> {
  const user = await fetchUserFromDatabase(id);
  if (!user) return null;

  // Add related users to the user
  const relatedUsers = await fetchRelatedUsers(id);
  return {
    ...user,
    relatedUsers,
  };
}

